function strongPasswordChecker(password) {
  const n = password.length;
  let missing = 3;
  if (/[a-z]/.test(password)) missing--;
  if (/[A-Z]/.test(password)) missing--;
  if (/[0-9]/.test(password)) missing--;
  if (n < 6) {
    return Math.max(missing, 6 - n);
  }
  const runs = [];
  let start = 0;
  for (let i = 1; i <= n; i++) {
    if (i === n || password[i] !== password[start]) {
      if (i - start >= 3) runs.push(i - start);
      start = i;
    }
  }
  const deletions = Math.max(0, n - 20);
  let left = deletions;
  for (let mod = 0; mod < 3; mod++) {
    for (let k = 0; k < runs.length; k++) {
      if (left > 0 && runs[k] >= 3 && runs[k] % 3 === mod) {
        const cut = Math.min(left, mod < 2 ? mod + 1 : runs[k] - 2);
        runs[k] -= cut;
        left -= cut;
      }
    }
  }
  let replacements = 0;
  for (const length of runs) {
    replacements += Math.floor(length / 3);
  }
  return deletions + Math.max(missing, replacements);
}

