function strongPasswordChecker(password) {
  // Exact DP over edit scripts. State: last written char code (0 = none or a fresh char that
  // differs from its neighbours), its run length, the mask of kinds present, and the length written.
  const kindOf = ch => (ch >= 'a' && ch <= 'z') ? 1 : (ch >= 'A' && ch <= 'Z') ? 2 : (ch >= '0' && ch <= '9') ? 4 : 0;
  const MAXLEN = 20, SIZE = 128 * 3 * 8 * (MAXLEN + 1);
  const at = (last, run, mask, len) => ((last * 3 + run) * 8 + mask) * (MAXLEN + 1) + len;
  const close = layer => {
    // Insert fresh characters of any kind; lengths only grow, so process them in increasing order.
    for (let len = 0; len < MAXLEN; len++)
      for (let last = 0; last < 128; last++)
        for (let run = 0; run < 3; run++)
          for (let mask = 0; mask < 8; mask++) {
            const cost = layer[at(last, run, mask, len)];
            if (cost === Infinity) continue;
            for (const kind of [1, 2, 4]) {
              const to = at(0, 1, mask | kind, len + 1);
              if (cost + 1 < layer[to]) layer[to] = cost + 1;
            }
          }
  };
  let layer = new Float64Array(SIZE).fill(Infinity);
  layer[at(0, 0, 0, 0)] = 0;
  close(layer);
  for (const ch of password) {
    const code = ch.charCodeAt(0), kind = kindOf(ch);
    const next = new Float64Array(SIZE).fill(Infinity);
    const relax = (i, c) => { if (c < next[i]) next[i] = c; };
    for (let last = 0; last < 128; last++)
      for (let run = 0; run < 3; run++)
        for (let mask = 0; mask < 8; mask++)
          for (let len = 0; len <= MAXLEN; len++) {
            const cost = layer[at(last, run, mask, len)];
            if (cost === Infinity) continue;
            relax(at(last, run, mask, len), cost + 1); // delete ch
            if (len === MAXLEN) continue;
            if (last !== code) relax(at(code, 1, mask | kind, len + 1), cost); // keep ch
            else if (run < 2) relax(at(code, run + 1, mask | kind, len + 1), cost);
            for (const k of [1, 2, 4]) relax(at(0, 1, mask | k, len + 1), cost + 1); // replace ch
          }
    close(next);
    layer = next;
  }
  let best = Infinity;
  for (let last = 0; last < 128; last++)
    for (let run = 0; run < 3; run++)
      for (let len = 6; len <= MAXLEN; len++) best = Math.min(best, layer[at(last, run, 7, len)]);
  return best;
}

