function generate(rand, size) {
  const pools = ['aA1.!', 'abAB01', 'aaab', 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.!', 'a1'];
  const pool = pools[Math.floor(rand() * pools.length)];
  const target = size === 'large' ? 40 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 32);
  let password = '';
  while (password.length < target) {
    const ch = pool[Math.floor(rand() * pool.length)];
    const run = rand() < 0.5 ? 1 : 1 + Math.floor(rand() * 9);
    password += ch.repeat(Math.min(run, target - password.length));
  }
  return [password];
}
